{
  "highlights": [
    {
      "start_time": 386000,
      "end_time": 401000,
      "description": "婚礼吉时礼炮响起，一辆豪车停在门口，穿黑丝绒礼服的顾砚下车伸手邀沈念走，字幕显示他是沈念的青梅竹马。"
    },
    {
      "start_time": 401000,
      "end_time": 410000,
      "description": "沈念伸手握住顾砚的手，江离成崩溃大喊着冲过来想阻止，被沈家人当场拦住。"
    },
    {
      "start_time": 423000,
      "end_time": 430000,
      "description": "沈父当众宣布今天的婚礼取消，明确表示沈家没有江离成这样的女婿。"
    },
    {
      "start_time": 61000,
      "end_time": 69000,
      "description": "沈念对偏袒伴娘的江离成彻底心寒，暗下决心要换新郎，拿出手机发消息叫人8:50来接自己抢亲。"
    },
    {
      "start_time": 315000,
      "end_time": 337000,
      "description": "沈父最后一次问江离成出不出门，江离成明确回答等苏婉婉画完；沈念戴上胸花，甩开他的手独自往外走。"
    },
    {
      "start_time": 147000,
      "end_time": 153000,
      "description": "江离成立刻站到苏婉婉身边护着她，当众跟沈父顶嘴，称是自己让她补妆的，要怪就怪自己。"
    },
    {
      "start_time": 121000,
      "end_time": 128000,
      "description": "苏婉婉故意惊呼自己补错了眼线颜色，称要换成黑色重新补，继续拖延出阁吉时。"
    },
    {
      "start_time": 442000,
      "end_time": 447000,
      "description": "江离成崩溃质问顾砚凭什么带走沈念，顾砚淡定回应，凭自己8:58准时到，没误吉时。"
    },
    {
      "start_time": 199000,
      "end_time": 204000,
      "description": "沈念给江离成最后选择机会，问他是现在跟自己走，还是继续等苏婉婉。"
    },
    {
      "start_time": 4500,
      "end_time": 8000,
      "description": "婚礼接亲吉时将至，众人正催新娘出门，伴娘苏婉婉突然叫停，称自己眼线花了要补妆。"
    },
    {
      "start_time": 161000,
      "end_time": 179000,
      "description": "江离成拿两人7年感情说事，称婚礼不会因为晚几分钟就办不成；沈念内心彻底看清，他是笃定自己一定会嫁才敢让自己受委屈。"
    },
    {
      "start_time": 363000,
      "end_time": 368000,
      "description": "沈念外婆站出来力挺外孙女，说吉时到了就出阁，不管怎么样，咱不委屈自己。"
    },
    {
      "start_time": 498000,
      "end_time": 508000,
      "description": "顾砚拿出一束铃兰递给沈念，笑着说自己本来打算抢亲，现在名正言顺娶她更好。"
    },
    {
      "start_time": 599000,
      "end_time": 609000,
      "description": "江离成终于醒悟，从头到尾真正把沈念推走的人是他自己，捂着胸口痛苦不已，立刻开车去追。"
    },
    {
      "start_time": 614000,
      "end_time": 622000,
