    },
    {
      "start_time": 417000,
      "end_time": 423000,
      "description": "沈母哭着送沈念上车，摸着她的背安慰，让她别怕，爸妈都在身后支持她。"
    },
    {
      "start_time": 249000,
      "end_time": 257000,
